INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1459509-phys399', 'stk-user8581', 'PHYS 399', 'info', '{"desc": "تجربة 3 من طلاب جامعتنا في التدريب الصيفي في KAUST\nوتخصصاتهم : Math + Physics , Electrical Engineering\n\nالتدريب الصيفي بجامعة الملك عبدالله للعلوم والتقنية KAUST", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/50", "user": "user8581", "ts": 1475561596000, "tid": 170460, "pn": 50}}', 1475561596000, 1794792308, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1315928-phys399', 'stk-user82', 'PHYS 399', 'info', '{"desc": "كملاحظاتي المبدئية على السيرة حقتك … لاحظت التالي :\n\nفي المعلومات الخاصة فيك بالأعلى … تقدر تستغني عن سطر Home Address … الأمر راجع لك … تخليه أو تشيله هذا راجع لك … لكن لابد من وجود الإيميل ورقم الجوال … وممكن رقم جوال قريب لك … مثلا أخوك … بس يكون رقمك هو الأول من جهة اليسار\n\nكلمة (Objectives) شيل منها حرف (s) … وهي ما يحتاج … جيدة ، لكن طويلة شوي … المفروض ما تتعدى 3 سطور بأي حال من الأحوال …\n\nلاحظت إنك كاتب اسم الشركة اللي تنوي تقدم عليها … مثل Schlumberger … وهذا ما فيه أي مشكلة على الإطلاق … ولكن انتبه ! انتبه أنك ترسلها لأي شركة ثانية بدون ما تعدّل اسم الشركة … 😏\n\nEducation … خاصية وضع خطوط تحت الكلمات مثل كذا … أحس إنها تربك القارئ شوي … ممكن نستبدلها بالخطوط الغامقة وطبعا لازم يكون حجم الخط هو 12 للكلام العادي … مو العناوين … العناوين ممكن تكون 14 … وطبعا هالشئ يحكمه عدد صفحات CV … وبشكل عام الخريجين الجدد لازم ما تتعدى الـ CV حقتهم صفحة واحدة 🙂\n\nنرجع للـ Education … أشوف إنها المفروض تكون كذا\n\nBSc. Geophysics, West Michigan University, XXXXXX, USA, July 2013 (GPA 2.5/4.00)\nغيّر كلمة XXXXXX باسم المنطقة أو الولاية اللي فيها هذه الجامعة\n\nممكن تحت تحتها sub-point … مثل كذا :\n\nGraduation Project\nوتكتب تحته وصف مختصر جدا للمشروع … ويمكن ما هو ضروري إنك تكتب كم أخذت في هذه المادة\nإذا فيه مشاريع ثانية سويتها أو بحوث قوية كتبتها … اكتبها بنفس الشكل\n\nبخصوص المواد اللي أخذتها … رأيي إنك ما تذكرها لسبب واحد … لأنها موجودة في السجل الأكاديمي (Transcript) … وأي واحد يبي معلومات عنها ، بيحصلها في السجل الأكاديمي\n\nبعد التعليم … يجي Work Experience\n\nهنا لازم تحط التدريب الصيفي … العمل الجزئي … ممكن تحط العمل التطوعي ولازم تحطه بهذا الشكل :\n\nEmployer Name, City September 2013 – Present\nYour Position or role:\n\nlist of duties and responsiblities\n\nlist of duties and responsiblities\n\nlist of duties and responsiblities\n\n…\n\nوتبدأ من الأحدث إلى الأقدم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/154921/21", "user": "user82", "ts": 1388996479000, "tid": 154921, "pn": 21}}', 1388996479000, 1794792308, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
